[{"id":"Q1","statement":"Electron rest energy E0 = 8.1871058e-14 J","inputs":"m_e = 9.1093837e-31 kg; c = 2.99792458e8 m/s","formula":"E0 = m_e*c^2"},{"id":"Q2","statement":"ZBW angular frequency omega_ZBW = 1.55268e21 rad/s","inputs":"E0 = 8.1871058e-14 J; hbar = 1.054571817e-34 J s","formula":"omega_ZBW = 2*E0/hbar"},{"id":"Q3","statement":"ZBW ordinary frequency f_ZBW = 2.4710e20 Hz","inputs":"omega_ZBW = 1.55268e21 rad/s","formula":"f_ZBW = omega_ZBW/(2*pi)"},{"id":"Q4","statement":"Reduced Compton wavelength lambda_C = 3.8616e-13 m","inputs":"hbar = 1.054571817e-34 J s; m_e = 9.1093837e-31 kg; c = 2.99792458e8 m/s","formula":"lambda_C = hbar/(m_e*c)"},{"id":"Q5","statement":"Momentum spread at Compton localization Delta_p = 1.3654e-22 kg m/s","inputs":"hbar = 1.054571817e-34 J s; lambda_C = 3.8616e-13 m","formula":"Delta_p = hbar/(2*lambda_C)"},{"id":"Q6","statement":"Weak-coupling relative frequency shift 2e-6 and delta_omega = 3.11e15 rad/s for |g| = 1e-3*Delta_E","inputs":"|g|/Delta_E = 1e-3; omega_ZBW = 1.55268e21 rad/s","formula":"sqrt(1+4*(1e-3)^2) - 1; delta_omega = (sqrt(1+4e-6)-1)*omega_ZBW"},{"id":"Q7","statement":"Population modulation depth A_pop = 4.0e-6 for |g| = 1e-3*Delta_E","inputs":"|g|/Delta_E = 1e-3","formula":"A_pop = 4*(g/Delta_E)^2/(1+4*(g/Delta_E)^2)"},{"id":"Q8","statement":"2-adic ball measure D2(n) = 2^-n, e.g. D2(10) = 9.77e-4","inputs":"n = 10","formula":"D2(n) = 2^-n"}]